	}
	branch, _ := gitScalar(ctx, opts.Runner, repoDir, "branch", "--show-current")
	defaultBranch, defaultWarnings := detectDefaultBranch(ctx, opts.Runner, repoDir)
	dirty := worktreeDirty(ctx, opts.Runner, repoDir)
