  1447		}
  1448		if err := validateSemanticSchema(header.SchemaVersion); err != nil {
  1449			return semanticHeader{}, semanticCounts{}, fmt.Errorf("semantic snapshot schema unsupported: %w", err)
  1450		}
  1451		line := 1
