  1453		for scanner.Scan() {
  1454			line++
  1455			text := bytes.TrimSpace(scanner.Bytes())
  1456			if len(text) == 0 {
  1457				continue
  1458			}
  1459			var record semanticRecord
  1460			if err := json.Unmarshal(text, &record); err != nil {
  1461				return semanticHeader{}, semanticCounts{}, fmt.Errorf("parse semantic snapshot line %d: %w", line, err)
  1462			}
